def discountPrices(sentence, discount):
    factor = 100 - discount
    words = sentence.split(' ')
    for i, w in enumerate(words):
        if len(w) > 1 and w[0] == '$' and w[1:].isdigit():
            price = int(w[1:])
            cents = price * factor
            dollars, c = divmod(cents, 100)
            words[i] = f'${dollars}.{c:02d}'
    return ' '.join(words)

